            //RCLCPP_INFO(this->get_logger(), "RTCM Data (Hex): %s", hex_stream.str().c_str());

            // Publish RTCM message
            std_msgs::msg::UInt8MultiArray msg;
            msg.data.assign(buffer.begin(), buffer.end());

            rtcm_pub_->publish(msg);
        } catch (std::exception &e) {
            RCLCPP_ERROR(this->get_logger(), "Error reading serial data: %s", e.what());
        }
    }`

