        mavsdk::Rtk::RtcmData mav_rtcm_data;

        // Convert std::vector<uint8_t> to std::string
        mav_rtcm_data.data.assign(rtcm_data.begin(), rtcm_data.end());

        // Debugging: Print RTCM Data in HEX
        std::ostringstream oss;
        for (uint8_t byte : rtcm_data) {
            oss << std::hex << std::setw(2) << std::setfill('0') << (int)byte << " ";
        }
        //RCLCPP_INFO(this->get_logger(), "RTCM Data (Hex): %s", oss.str().c_str());

        mavsdk::Rtk::Result result = rtk_plugin_->send_rtcm_data(mav_rtcm_data);
        if (result == mavsdk::Rtk::Result::Success) {
            RCLCPP_INFO(this->get_logger(), "RTCM Data Size: %lu bytes", rtcm_data.size());
            RCLCPP_INFO(this->get_logger(), "Successfully sent RTCM data to Pixhawk");
        } else {
            RCLCPP_WARN(this->get_logger(), "Failed to forward RTCM data: %d", static_cast<int>(result));
        }
    }`

